package com.improvedchat;

import java.util.HashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.ChatMessageType;

public final class ChatDisplayText {
    private static final Pattern TEMPLATE = Pattern.compile("<(str_[A-Za-z0-9_]+)(?:=([^<>]*))?>");

    private ChatDisplayText() {}

    public static String normalize(ChatMessageType type, String text) {
        if (text == null) return "";
        if (type == ChatMessageType.CLAN_GIM_CHAT && text.startsWith("|")) text = text.substring(1);
        else if (type == ChatMessageType.GAMEMESSAGE || type == ChatMessageType.CLAN_MESSAGE
                || type == ChatMessageType.CLAN_GIM_MESSAGE) {
            if (type == ChatMessageType.CLAN_GIM_MESSAGE && text.startsWith("|")) text = text.substring(1);
            int pipe = text.indexOf('|');
            if (pipe >= 0) text = text.substring(pipe + 1);
        } else if (type == ChatMessageType.BROADCAST) {
            int pipe = text.indexOf('|');
            if (pipe >= 0) text = text.substring(0, pipe);
        }
        return expandTemplates(text);
    }

    public static String expandTemplates(String text) {
        Map<String, String> values = new HashMap<>();
        Matcher matcher = TEMPLATE.matcher(text);
        StringBuffer result = new StringBuffer();
        while (matcher.find()) {
            String value = matcher.group(2);
            if (value != null) values.put(matcher.group(1), value);
            matcher.appendReplacement(result, Matcher.quoteReplacement(value != null ? "" : values.getOrDefault(matcher.group(1), "")));
        }
        matcher.appendTail(result);
        return result.toString();
    }
}

package com.improvedchat;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import net.runelite.client.plugins.chatfilter.ChatFilterConfig;
import net.runelite.client.util.Text;
import org.apache.commons.lang3.StringUtils;

public final class ChatMessageFilter {
    private List<Pattern> patterns = new ArrayList<>();
    private boolean stripAccents;

    public void rebuild(ChatFilterConfig cfg) {
        List<Pattern> compiled = new ArrayList<>();
        stripAccents = cfg.stripAccents();

        List<String> words = Text.fromCSV(BoundedPattern.source(cfg.filteredWords()));
        if (words.size() > BoundedPattern.MAX_RULES) BoundedPattern.reportLimit();
        words.stream()
                .limit(BoundedPattern.MAX_RULES)
                .map(this::maybeStripAccents)
                .map(s -> Pattern.compile(Pattern.quote(s), Pattern.CASE_INSENSITIVE))
                .forEach(compiled::add);

        for (String line : BoundedPattern.lines(cfg.filteredRegex())) {
            String trimmed = maybeStripAccents(line.trim());
            if (trimmed.isEmpty()) {
                continue;
            }
            Pattern p = compilePattern(trimmed);
            if (p != null) {
                compiled.add(p);
            }
        }

        patterns = compiled;
    }

    public boolean matches(String message) {
        if (message == null || patterns.isEmpty()) {
            return false;
        }

        String normalized = maybeStripAccents(message
                .replace('\u00A0', ' ')
                .replace("<lt>", "<")
                .replace("<gt>", ">")
                .replace("<at>", "@"));

        for (Pattern pattern : patterns) {
            if (BoundedPattern.find(pattern, normalized)) {
                return true;
            }
        }
        return false;
    }

    private String maybeStripAccents(String input) {
        return stripAccents ? StringUtils.stripAccents(input) : input;
    }

    private static Pattern compilePattern(String pattern) {
        try {
            return BoundedPattern.compile(pattern, Pattern.CASE_INSENSITIVE);
        } catch (PatternSyntaxException ex) {
            return null;
        }
    }
}

