package com.improvedchat.chatbox.resize.internal;

import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;
import java.awt.Rectangle;

public final class Widgets {
    private Widgets() {}

    public static Widget chatSlot(Client client) {
        Widget universe = client.getWidget(InterfaceID.Chatbox.UNIVERSE);
        return universe == null ? null : universe.getParent();
    }

    public static Widget mountedRoot(Client client, int group) {
        Widget root = client.getWidget(group, 0);
        if (root == null) return null;
        for (Widget up = root.getParent(); up != null && WidgetUtil.componentToInterface(up.getId()) == group; up = up.getParent()) root = up;
        return root;
    }

    public static Rectangle liveBounds(Widget widget) {
        int x = widget.getRelativeX();
        int y = widget.getRelativeY();

        for (Widget up = widget.getParent(); up != null; up = up.getParent()) {
            x += up.getRelativeX();
            y += up.getRelativeY();
        }
        return new Rectangle(x, y, widget.getWidth(), widget.getHeight());
    }

    public static void revalidateChildren(Widget widget) {
        revalidateAll(widget.getStaticChildren());
        revalidateAll(widget.getDynamicChildren());
    }

    static void revalidateAll(Widget[] children) {
        if (children == null) return;
        for (Widget child : children) {
            if (child == null) continue;
            child.revalidate();
            if (child.getId() == InterfaceID.Chatbox.SCROLLAREA) continue;
            revalidateChildren(child);
        }
    }

    @SuppressWarnings("deprecation") public static void setWidth(Widget widget, int width) { widget.setWidth(width); }
    @SuppressWarnings("deprecation") public static void setHeight(Widget widget, int height) { widget.setHeight(height); }
}

package com.improvedchat.compat;

import java.util.Locale;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.PluginManager;

@Singleton
public final class ModernChatCompatibility
{
    static final String MODERN_CHAT_CLASS = "com.modernchat.ModernChatPlugin";
    static final String MODERN_CHAT_GROUP = "modernchat";
    static final String REDESIGN_KEY = "featureRedesign_Enabled";
    static final String TOGGLE_KEY = "featureToggle_Enabled";
    private static final String RUNELITE_GROUP = "runelite";

    @Inject
    private PluginManager pluginManager;

    @Inject
    private ConfigManager configManager;

    public ModernChatOwnership snapshot()
    {
        Plugin plugin = findModernChatPlugin();
        boolean active = plugin != null && pluginManager.isPluginActive(plugin);
        return ownership(active);
    }

    public ModernChatOwnership startupSnapshot()
    {
        Plugin plugin = findModernChatPlugin();
        boolean activeOrStarting = plugin != null
            && (pluginManager.isPluginActive(plugin) || pluginManager.isPluginEnabled(plugin));
        return ownership(activeOrStarting);
    }

    public boolean isModernChatActive()
    {
        Plugin plugin = findModernChatPlugin();
        return plugin != null && pluginManager.isPluginActive(plugin);
    }

    public boolean isModernChatPlugin(Plugin plugin)
    {
        return plugin != null && MODERN_CHAT_CLASS.equals(plugin.getClass().getName());
    }

    public boolean isOwnershipConfig(String group, String key)
    {
        return MODERN_CHAT_GROUP.equals(group) && (isRedesignKey(key) || isToggleKey(key));
    }

    public boolean isRedesignKey(String key)
    {
        return REDESIGN_KEY.equals(key);
    }

    public boolean isToggleKey(String key)
    {
        return TOGGLE_KEY.equals(key);
    }

    public boolean isModernChatEnableConfig(String group, String key)
    {
        if (!RUNELITE_GROUP.equals(group) || key == null)
        {
            return false;
        }

        Plugin plugin = findModernChatPlugin();
        if (plugin == null)
        {
            return false;
        }

        PluginDescriptor descriptor = plugin.getClass().getAnnotation(PluginDescriptor.class);
        if (descriptor == null)
        {
            return false;
        }

        String configName = descriptor.configName();
        if (configName == null || configName.isEmpty())
        {
            configName = plugin.getClass().getSimpleName();
        }
        return configName.toLowerCase(Locale.ROOT).equals(key);
    }

    private ModernChatOwnership ownership(boolean active)
    {
        return new ModernChatOwnership(
            active,
            readBoolean(configManager.getConfiguration(MODERN_CHAT_GROUP, REDESIGN_KEY), true),
            readBoolean(configManager.getConfiguration(MODERN_CHAT_GROUP, TOGGLE_KEY), true));
    }

    static boolean readBoolean(String value, boolean defaultValue)
    {
        return value == null ? defaultValue : Boolean.parseBoolean(value);
    }

    private Plugin findModernChatPlugin()
    {
        for (Plugin plugin : pluginManager.getPlugins())
        {
            if (isModernChatPlugin(plugin))
            {
                return plugin;
            }
        }
        return null;
    }
}

package com.improvedchat.compat;

public final class ModernChatOwnership
{
    private final boolean pluginActive;
    private final boolean redesignEnabled;
    private final boolean toggleEnabled;

    ModernChatOwnership(boolean pluginActive, boolean redesignEnabled, boolean toggleEnabled)
    {
        this.pluginActive = pluginActive;
        this.redesignEnabled = redesignEnabled;
        this.toggleEnabled = toggleEnabled;
    }

    public boolean isPluginActive()
    {
        return pluginActive;
    }

    public boolean blocksGeometry()
    {
        return pluginActive && redesignEnabled;
    }

    public boolean blocksVisibility()
    {
        return pluginActive && (redesignEnabled || toggleEnabled);
    }

    public boolean blocksNativePresentation()
    {
        return pluginActive && redesignEnabled;
    }
}

package com.improvedchat.dialogue;

import com.improvedchat.ImprovedChatConfig;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.events.ClientTick;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.ui.overlay.OverlayManager;

@Singleton
public final class DialogueFontsModule {
    @Inject private ImprovedChatConfig config;
    @Inject private ClientThread clientThread;
    @Inject private EventBus eventBus;
    @Inject private OverlayManager overlayManager;
    @Inject private DialogueFontsOverlay overlay;
    @Inject private DialogueWidgetManager widgetManager;

    private boolean started;

    public synchronized void startUp() {
        if (started || !config.enableDialogueFonts()) {
            return;
        }
        started = true;
        overlayManager.add(overlay);
        eventBus.register(this);
    }

    public synchronized void shutDown() {
        if (!started) {
            return;
        }
        started = false;
        eventBus.unregister(this);
        overlayManager.remove(overlay);
        widgetManager.restoreAll();
        overlay.setState(null);
    }

    @Subscribe
    public void onClientTick(ClientTick event) {
        if (!started) {
            return;
        }
        overlay.setState(widgetManager.getCurrentDialogue());
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if (!started || !ImprovedChatConfig.GROUP.equals(event.getGroup())) {
            return;
        }

        String key = event.getKey();
        if ("replaceNpc".equals(key)
            || "replacePlayer".equals(key)
            || "replaceOptions".equals(key)
            || "replaceSprite".equals(key)) {
            clientThread.invoke(() -> {
                widgetManager.restoreAll();
                overlay.setState(null);
            });
        }
    }
}

