@Singleton
public class NativeChatBackgroundOverlay extends Overlay {
    private final Client client;
    private final ImprovedChatConfig config;
    private final SpriteManager sprites;
    private final ClientThread clientThread;
    private final EventBus events;
    private final List<Widget> hiddenForFrame = new ArrayList<>();
    private List<Part> cachedParts;
    private Rectangle cachedClip;
    private int cachedInset;
    private BufferedImage cachedImage;
    private Rectangle paintBounds;
    private boolean prepared;
    private volatile boolean running;

    @Inject
    public NativeChatBackgroundOverlay(Client client, ImprovedChatConfig config, SpriteManager sprites,
            ClientThread clientThread, EventBus events) {
        this.client = client; this.config = config; this.sprites = sprites;
        this.clientThread = clientThread; this.events = events;
        setPosition(OverlayPosition.DYNAMIC); setLayer(OverlayLayer.MANUAL);
        drawAfterLayer(InterfaceID.Chatbox.CHAT_BACKGROUND);
    }

    public void startUp() { running = true; events.register(this); }
    public void shutDown() {
        running = false; events.unregister(this);
        clientThread.invoke(() -> { if (!running) { restore(); cachedImage = null; cachedParts = null; } });
    }

    @Subscribe(priority = -100)
    public void onBeforeRender(BeforeRender event) {
        restore();
        if (!running || !config.chatboxBorder() || !config.chatboxBorderRounded()
                || client.getGameState() != GameState.LOGGED_IN
                || client.getVarcIntValue(VarClientID.CHAT_VIEW) == 1337) return;
        Widget area = client.getWidget(InterfaceID.Chatbox.CHATAREA);
        Widget messages = client.getWidget(InterfaceID.Chatbox.SCROLLAREA);
        Widget background = client.getWidget(InterfaceID.Chatbox.CHAT_BACKGROUND);
        if (area == null || area.isHidden() || messages == null || messages.isHidden()
                || background == null || background.isHidden()) return;
        Rectangle bounds = Widgets.liveBounds(area);
        if (bounds.width < 2 || bounds.height < 2 || bounds.width > 4096 || bounds.height > 4096) return;
        Rectangle clip = Widgets.liveBounds(background).intersection(bounds);
        if (clip.isEmpty()) return;
        clip.translate(-bounds.x, -bounds.y);
        List<Widget> children = new ArrayList<>();
        if (background.getDynamicChildren() != null) children.addAll(Arrays.asList(background.getDynamicChildren()));
        if (background.getStaticChildren() != null) children.addAll(Arrays.asList(background.getStaticChildren()));
        List<Part> parts = new ArrayList<>();
        List<Widget> visible = new ArrayList<>();
        for (Widget child : children) {
            if (child == null || child.isHidden()) continue;
            Rectangle childBounds = Widgets.liveBounds(child);
            childBounds.translate(-bounds.x, -bounds.y);
            if (!childBounds.intersects(clip)) continue;
            BufferedImage sprite = null;
            if (child.getType() == WidgetType.GRAPHIC) {

                SpritePixels override = client.getWidgetSpriteOverrides().get(child.getId());
                if (override == null) override = client.getSpriteOverrides().get(child.getSpriteId());
                sprite = override == null ? sprites.getSprite(child.getSpriteId(), 0) : override.toBufferedImage();
                if (sprite == null || child.getBorderType() != 0
                        || child.getSpriteTiling() && (child.isFlippedHorizontally() || child.isFlippedVertically())) return;
            } else if (child.getType() != WidgetType.RECTANGLE || !child.isFilled()) {
                return;
            }
            parts.add(new Part(childBounds, child.getTextColor(), child.getOpacity(), sprite,
                    child.getSpriteTiling(), child.isFlippedHorizontally(), child.isFlippedVertically()));
            visible.add(child);
        }
        if (parts.isEmpty()) return;
        int inset = config.chatboxBorderThickness().getPixels() / 2;
        if (cachedImage == null || cachedImage.getWidth() != bounds.width || cachedImage.getHeight() != bounds.height
                || !parts.equals(cachedParts) || !clip.equals(cachedClip) || inset != cachedInset) {
            cachedImage = paint(parts, clip, bounds.width, bounds.height, inset);
            cachedParts = parts; cachedClip = clip; cachedInset = inset;
        }
        paintBounds = bounds;

        hiddenForFrame.addAll(visible);
        for (Widget child : visible) child.setHidden(true);
        prepared = true;
    }

    @Override public Dimension render(Graphics2D graphics) {
        try {
            Widget area = client.getWidget(InterfaceID.Chatbox.CHATAREA);
            if (prepared && running && area != null && !area.isHidden())
                graphics.drawImage(cachedImage, paintBounds.x, paintBounds.y, null);
        } finally { restore(); }
        return null;
    }

    @Subscribe public void onScriptPreFired(ScriptPreFired event) { restore(); }
    @Subscribe public void onGameStateChanged(GameStateChanged event) { restore(); }

    private void restore() {
        for (Widget child : hiddenForFrame) child.setHidden(false);
        hiddenForFrame.clear(); prepared = false;
    }

    private static BufferedImage paint(List<Part> parts, Rectangle clip, int width, int height, int inset) {
        BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        try {
            g.setClip(clip);
            for (Part part : parts) {
                Rectangle b = part.bounds;
                g.setComposite(AlphaComposite.SrcOver.derive((256 - Math.max(0, Math.min(255, part.opacity))) / 256f));
                if (part.sprite == null) { g.setColor(new Color(part.color)); g.fillRect(b.x, b.y, b.width, b.height); }
                else if (part.tiled && !part.flipX && !part.flipY) {
                    g.setPaint(new TexturePaint(part.sprite, new Rectangle(b.x, b.y, part.sprite.getWidth(), part.sprite.getHeight())));
                    g.fillRect(b.x, b.y, b.width, b.height);
                } else {
                    g.drawImage(part.sprite, b.x, b.y, b.x + b.width, b.y + b.height,
                            part.flipX ? part.sprite.getWidth() : 0, part.flipY ? part.sprite.getHeight() : 0,
                            part.flipX ? 0 : part.sprite.getWidth(), part.flipY ? 0 : part.sprite.getHeight(), null);
                }
            }
            g.setClip(null);
            BufferedImage mask = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
            Graphics2D shape = mask.createGraphics();
            try {
                shape.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                shape.setColor(Color.WHITE);
                shape.fill(new RoundRectangle2D.Double(inset, inset, Math.max(0, width - 1 - inset * 2),
                        Math.max(0, height - 1 - inset * 2), 16, 16));
            } finally { shape.dispose(); }
            g.setComposite(AlphaComposite.DstIn); g.drawImage(mask, 0, 0, null);
        } finally { g.dispose(); }
        return image;
    }

    private static final class Part {
        final Rectangle bounds; final int color, opacity; final BufferedImage sprite;
        final boolean tiled, flipX, flipY;
        Part(Rectangle bounds, int color, int opacity, BufferedImage sprite, boolean tiled, boolean flipX, boolean flipY) {
            this.bounds = bounds; this.color = color; this.opacity = opacity; this.sprite = sprite;
            this.tiled = tiled; this.flipX = flipX; this.flipY = flipY;
        }
        @Override public boolean equals(Object other) {
            if (!(other instanceof Part)) return false;
            Part p = (Part) other;
            return bounds.equals(p.bounds) && color == p.color && opacity == p.opacity && sprite == p.sprite
                    && tiled == p.tiled && flipX == p.flipX && flipY == p.flipY;
        }
        @Override public int hashCode() { return Objects.hash(bounds, color, opacity, sprite, tiled, flipX, flipY); }
    }
}

package com.improvedchat.overlay;

import com.improvedchat.ImprovedChatConfig;
import com.improvedchat.chatbox.resize.internal.Widgets;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

@Singleton
public final class NativeChatBorderOverlay extends Overlay {
    private final Client client;
    private final ImprovedChatConfig config;
    private final OverlayConfig style = new OverlayConfig();

    @Inject
    public NativeChatBorderOverlay(Client client, ImprovedChatConfig config) {
        this.client = client;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.MANUAL);
        drawAfterInterface(InterfaceID.CHATBOX);
        style.setBorderEnabled(true);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!config.chatboxBorder() || client.getGameState() != GameState.LOGGED_IN
                || client.getVarcIntValue(VarClientID.CHAT_VIEW) == 1337) return null;
        Widget area = client.getWidget(InterfaceID.Chatbox.CHATAREA);
        Widget messages = client.getWidget(InterfaceID.Chatbox.SCROLLAREA);
        if (area == null || area.isHidden() || messages == null || messages.isHidden()) return null;
        Rectangle bounds = Widgets.liveBounds(area);
        if (bounds.width <= 1 || bounds.height <= 1) return null;

        style.setBorderColour(config.chatboxBorderColor());
        style.setBorderThickness(config.chatboxBorderThickness());
        style.setRgbBorder(config.chatboxBorderRgb());
        style.setRgbCycleSeconds(config.chatboxBorderRgbSeconds());
        style.setRoundedCorners(config.chatboxBorderRounded());
        Graphics2D frame = (Graphics2D) graphics.create();
        try {
            frame.clipRect(bounds.x, bounds.y, bounds.width, bounds.height);
            frame.translate(bounds.x, bounds.y);
            AttentionEngine.drawBorder(frame, style, bounds.width, bounds.height, System.currentTimeMillis());
        } finally {
            frame.dispose();
        }
        return null;
    }
}

package com.improvedchat.overlay;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.Iterator;
import javax.imageio.ImageIO;
import javax.imageio.ImageReader;
import javax.imageio.metadata.IIOMetadataNode;
import javax.imageio.stream.MemoryCacheImageInputStream;
import org.w3c.dom.Node;

final class OverlayBackgroundImage {
    private static final int MAX_BYTES = 10 * 1024 * 1024;
    private static final int MAX_PIXELS = 8_000_000;
    private static final int MAX_FRAMES = 300;
    private static final long MAX_GIF_WORK_PIXELS = 128_000_000;
    private static final int RENDER_PIXELS = 512 * 512;
    private static final int ANIMATION_PIXELS = 4 * 1024 * 1024;
    final boolean gif;
    final long bytes;
    private final BufferedImage[] frames;
    private final long[] ends;
    private final int plays;

    private OverlayBackgroundImage(boolean gif, BufferedImage[] frames, long[] ends, int plays) {
        this.gif = gif;
        this.frames = frames;
        this.ends = ends;
        this.plays = plays;
        long size = 0;
        for (BufferedImage frame : frames) size += 4L * frame.getWidth() * frame.getHeight();
        bytes = size;
    }

    BufferedImage frame(long elapsedNanos) {
        if (frames.length == 1) return frames[0];
        long elapsed = Math.max(0, elapsedNanos);
        long duration = ends[ends.length - 1];
        if (plays > 0 && elapsed / duration >= plays) return frames[frames.length - 1];
        long time = elapsed % duration;
        int low = 0, high = ends.length - 1;
        while (low < high) {
            int mid = (low + high) >>> 1;
            if (time < ends[mid]) high = mid;
            else low = mid + 1;
        }
        return frames[low];
    }

    static byte[] readBytes(InputStream input) throws IOException {
        byte[] bytes = input.readNBytes(MAX_BYTES + 1);
        if (bytes.length > MAX_BYTES) throw new IOException("Choose a PNG, JPEG or GIF smaller than 10 MB.");
        return bytes;
    }

    static OverlayBackgroundImage read(byte[] bytes) throws IOException {
        try (MemoryCacheImageInputStream stream = new MemoryCacheImageInputStream(new ByteArrayInputStream(bytes))) {
            Iterator<ImageReader> readers = ImageIO.getImageReaders(stream);
            if (!readers.hasNext()) throw new IOException("Choose a PNG, JPEG or GIF image.");
            ImageReader reader = readers.next();
            try {
                String format = reader.getFormatName();
                boolean gif = "gif".equalsIgnoreCase(format);
                if (!gif && !"png".equalsIgnoreCase(format) && !"jpeg".equalsIgnoreCase(format))
                    throw new IOException("Choose a PNG, JPEG or GIF image.");
                reader.setInput(stream, false, false);
                if (gif) return readGif(reader);
                int width = reader.getWidth(0), height = reader.getHeight(0);
                checkSize(width, height);
                BufferedImage decoded = reader.read(0);
                try {
                    return new OverlayBackgroundImage(false, new BufferedImage[]{normalize(decoded, RENDER_PIXELS)}, new long[]{1}, 1);
                } finally { decoded.flush(); }
            } finally { reader.dispose(); }
        }
    }

    private static OverlayBackgroundImage readGif(ImageReader reader) throws IOException {
        Node stream = reader.getStreamMetadata().getAsTree("javax_imageio_gif_stream_1.0");
        Node screen = child(stream, "LogicalScreenDescriptor");
        int width = number(screen, "logicalScreenWidth"), height = number(screen, "logicalScreenHeight");
        checkSize(width, height);
        int count = reader.getNumImages(true);
        if (count < 1 || count > MAX_FRAMES) throw new IOException("Choose a GIF with at most 300 frames.");
        if ((long) width * height * count > MAX_GIF_WORK_PIXELS)
            throw new IOException("This GIF is too large to animate. Choose a smaller or shorter GIF.");
        FrameInfo[] info = new FrameInfo[count];
        int plays = 1;
        for (int i = 0; i < count; i++) {
            Node metadata = reader.getImageMetadata(i).getAsTree("javax_imageio_gif_image_1.0");
            info[i] = new FrameInfo(metadata);
            FrameInfo frame = info[i];
            if (frame.width < 1 || frame.height < 1 || frame.x < 0 || frame.y < 0
                    || (long) frame.x + frame.width > width || (long) frame.y + frame.height > height)
                throw new IOException("This GIF has invalid frame dimensions.");
            Node extensions = child(metadata, "ApplicationExtensions");
            for (Node extension = extensions == null ? null : extensions.getFirstChild(); extension != null; extension = extension.getNextSibling()) {
                String application = attribute(extension, "applicationID");
                String authentication = attribute(extension, "authenticationCode");
                if (("NETSCAPE".equals(application) && "2.0".equals(authentication))
                        || ("ANIMEXTS".equals(application) && "1.0".equals(authentication))) {
                    Object data = ((IIOMetadataNode) extension).getUserObject();
                    if (data instanceof byte[] && ((byte[]) data).length >= 3 && ((byte[]) data)[0] == 1) {
                        byte[] loop = (byte[]) data;
                        int repeats = (loop[1] & 255) | ((loop[2] & 255) << 8);
                        plays = repeats == 0 ? 0 : repeats + 1;
                    }
                }
            }
        }
        int background = background(stream);
        BufferedImage canvas = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = canvas.createGraphics();
        BufferedImage[] frames = new BufferedImage[count];
        long[] ends = new long[count];
        long duration = 0;
        try {
            if (!info[0].transparent) {
                graphics.setColor(new Color(background, true));
                graphics.fillRect(0, 0, width, height);
            }
            for (int i = 0; i < count; i++) {
                FrameInfo frame = info[i];
                int[] previous = "restoreToPrevious".equals(frame.disposal)
                        ? canvas.getRGB(frame.x, frame.y, frame.width, frame.height, null, 0, frame.width) : null;
                BufferedImage decoded = reader.read(i);
                try {
                    graphics.setComposite(AlphaComposite.SrcOver);
                    graphics.drawImage(decoded, frame.x, frame.y, null);
                } finally { decoded.flush(); }
                frames[i] = normalize(canvas, Math.min(RENDER_PIXELS, ANIMATION_PIXELS / count));
                duration += (frame.delay < 2 ? 100L : frame.delay * 10L) * 1_000_000L;
                ends[i] = duration;
                if (previous != null) canvas.setRGB(frame.x, frame.y, frame.width, frame.height, previous, 0, frame.width);
                else if ("restoreToBackgroundColor".equals(frame.disposal)) {
                    graphics.setComposite(AlphaComposite.Src);
                    graphics.setColor(new Color(frame.transparent ? 0 : background, true));
                    graphics.fillRect(frame.x, frame.y, frame.width, frame.height);
                }
            }
        } finally { graphics.dispose(); canvas.flush(); }
        return new OverlayBackgroundImage(true, frames, ends, plays);
    }

    private static int background(Node stream) throws IOException {
        Node table = child(stream, "GlobalColorTable");
        if (table == null) return 0;
        int index = number(table, "backgroundColorIndex");
        for (Node color = table.getFirstChild(); color != null; color = color.getNextSibling()) {
            if (number(color, "index") == index)
                return new Color(number(color, "red"), number(color, "green"), number(color, "blue")).getRGB();
        }
        return 0;
    }

    private static void checkSize(int width, int height) throws IOException {
        if (width < 1 || height < 1 || width > 8192 || height > 8192 || (long) width * height > MAX_PIXELS)
            throw new IOException("Choose an image with at most 8 million pixels and sides no longer than 8192 pixels.");
    }

    private static BufferedImage normalize(BufferedImage decoded, int pixels) {
        int width = decoded.getWidth(), height = decoded.getHeight();
        double scale = Math.min(1, Math.min(1024.0 / Math.max(width, height), Math.sqrt(pixels / ((double) width * height))));
        BufferedImage result = new BufferedImage(Math.max(1, (int) (width * scale)), Math.max(1, (int) (height * scale)), BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = result.createGraphics();
        try {
            graphics.setComposite(AlphaComposite.Src);
            graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
            graphics.drawImage(decoded, 0, 0, result.getWidth(), result.getHeight(), null);
        } finally { graphics.dispose(); }
        return result;
    }

    private static Node child(Node parent, String name) {
        if (parent == null) return null;
        for (Node node = parent.getFirstChild(); node != null; node = node.getNextSibling())
            if (name.equals(node.getNodeName())) return node;
        return null;
    }

    private static String attribute(Node node, String name) {
        Node value = node == null ? null : node.getAttributes().getNamedItem(name);
        return value == null ? "" : value.getNodeValue();
    }

    private static int number(Node node, String name) throws IOException {
        try { return Integer.parseInt(attribute(node, name)); }
        catch (NumberFormatException ex) { throw new IOException("This GIF has invalid metadata.", ex); }
    }

    private static final class FrameInfo {
        final int x, y, width, height, delay;
        final String disposal;
        final boolean transparent;
        FrameInfo(Node metadata) throws IOException {
            Node descriptor = child(metadata, "ImageDescriptor");
            x = number(descriptor, "imageLeftPosition"); y = number(descriptor, "imageTopPosition");
            width = number(descriptor, "imageWidth"); height = number(descriptor, "imageHeight");
            Node control = child(metadata, "GraphicControlExtension");
            delay = control == null ? 0 : number(control, "delayTime");
            disposal = attribute(control, "disposalMethod");
            transparent = "TRUE".equals(attribute(control, "transparentColorFlag"));
        }
    }
}

package com.improvedchat.overlay;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.util.HashMap;
import java.util.ArrayDeque;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.Executor;
import java.util.function.Consumer;
import java.util.function.LongSupplier;
import java.util.concurrent.RejectedExecutionException;
import java.util.regex.Pattern;
import javax.imageio.ImageIO;
import javax.imageio.stream.MemoryCacheImageOutputStream;
import javax.swing.SwingUtilities;
import net.runelite.client.util.Filepath;

public final class OverlayBackgroundImages {
    private static final long MAX_CACHED_BYTES = 64L * 1024 * 1024;
    private static final Pattern NAME = Pattern.compile("[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}\\.(png|gif)");
    private final Map<String, Entry> images = new HashMap<>();
    private final ArrayDeque<Work> work = new ArrayDeque<>();
    private final LongSupplier clock;
    private final long maxCachedBytes;
    private long cachedBytes;
    private long generation;
    private boolean importing;
    private boolean working;

    public OverlayBackgroundImages() { this(System::nanoTime, MAX_CACHED_BYTES); }

    OverlayBackgroundImages(LongSupplier clock, long maxCachedBytes) {
        this.clock = clock;
        this.maxCachedBytes = maxCachedBytes;
    }

    @FunctionalInterface
    public interface Directory { Filepath get() throws IOException; }

    public static boolean validName(String name) {
        return name != null && NAME.matcher(name).matches();
    }

    public synchronized void clear() { generation++; images.clear(); cachedBytes = 0; }
    public synchronized void retain(java.util.Set<String> names) {
        images.entrySet().removeIf(entry -> {
            if (names.contains(entry.getKey())) return false;
            if (entry.getValue().image != null) cachedBytes -= entry.getValue().image.bytes;
            return true;
        });
    }
    public synchronized boolean isImporting() { return importing; }
    public synchronized String status(String name) {
        Entry entry = images.get(name);
        return entry == null || entry.image != null ? null : entry.error == null ? "Loading image…" : entry.error;
    }

    public synchronized BufferedImage get(String name, Directory directory, Executor executor, Runnable changed) {
        Entry existing = images.get(name);
        if (existing != null) return existing.image == null ? null : existing.image.frame(clock.getAsLong() - existing.started);
        if (!validName(name)) return null;
        if (images.size() >= OverlayConfigStore.MAX_OVERLAYS) return null;
        Entry pending = new Entry(null, null, 0);
        images.put(name, pending);
        long requestGeneration = generation;
        enqueue(executor, () -> {
            synchronized (this) {
                if (requestGeneration != generation || images.get(name) != pending) return;
            }
            OverlayBackgroundImage image = null;
            String error = null;
            try (InputStream input = directory.get().joinSegment(name).openInputStream()) {
                image = OverlayBackgroundImage.read(OverlayBackgroundImage.readBytes(input));
            } catch (IOException | RuntimeException ex) {
                error = "Background image unavailable. Choose the image again.";
            }
            synchronized (this) {
                if (requestGeneration != generation || images.get(name) != pending) return;
                if (image != null && cachedBytes + image.bytes > maxCachedBytes) {
                    image = null;
                    error = "Background memory limit reached. Remove an unused image or choose a smaller GIF.";
                }
                if (image != null) cachedBytes += image.bytes;
                images.put(name, new Entry(image, error, clock.getAsLong()));
            }
            refresh(requestGeneration, changed);
        }, () -> {
            synchronized (this) {
                if (requestGeneration != generation || images.get(name) != pending) return;
                images.put(name, new Entry(null, "Background loading unavailable. Choose the image again.", 0));
            }
            refresh(requestGeneration, changed);
        });
        return null;
    }

    private void refresh(long requestGeneration, Runnable changed) {
        SwingUtilities.invokeLater(() -> {
            synchronized (this) { if (requestGeneration != generation) return; }
            changed.run();
        });
    }

    public void importImage(Filepath selected, Directory directory, Executor executor, Consumer<Result> callback) {
        long requestGeneration;
        synchronized (this) {
            if (importing) return;
            importing = true;
            requestGeneration = generation;
        }
        enqueue(executor, () -> {
            Result result;
            try (InputStream input = selected.openInputStream()) {
                byte[] bytes = OverlayBackgroundImage.readBytes(input);
                OverlayBackgroundImage image = OverlayBackgroundImage.read(bytes);
                synchronized (this) {
                    if (requestGeneration != generation) throw new IOException("Background selection cancelled.");
                    if (cachedBytes + image.bytes > maxCachedBytes || images.size() >= OverlayConfigStore.MAX_OVERLAYS)
                        throw new IOException("Background memory limit reached. Remove an unused image or choose a smaller GIF.");
                }
                Filepath folder = directory.get();
                folder.createDirectories();
                String name = UUID.randomUUID() + (image.gif ? ".gif" : ".png");
                Filepath file = folder.joinSegment(name);
                try (OutputStream output = file.openOutputStream()) {
                    if (image.gif) output.write(bytes);
                    else try (MemoryCacheImageOutputStream encoded = new MemoryCacheImageOutputStream(output)) {
                        if (!ImageIO.write(image.frame(0), "png", encoded)) throw new IOException("Could not save the background image.");
                    }
                }
                synchronized (this) {
                    if (requestGeneration != generation) throw new IOException("Background selection cancelled.");
                    cachedBytes += image.bytes;
                    images.put(name, new Entry(image, null, clock.getAsLong()));
                }
                result = new Result(name, null);
            } catch (IOException | RuntimeException ex) {
                result = new Result(null, ex instanceof IOException ? ex.getMessage() : "Could not load this image.");
            }
            finishImport(callback, result);
        }, () -> finishImport(callback, new Result(null, "Background loading unavailable. Choose the image again.")));
    }

    private void finishImport(Consumer<Result> callback, Result result) {
        synchronized (this) { importing = false; }
        SwingUtilities.invokeLater(() -> callback.accept(result));
    }

    private void enqueue(Executor executor, Runnable action, Runnable rejected) {
        synchronized (this) {
            work.addLast(new Work(action, rejected));
            if (working) return;
            working = true;
        }
        try { executor.execute(this::runWork); }
        catch (RejectedExecutionException ex) {
            ArrayDeque<Work> failed;
            synchronized (this) {
                failed = new ArrayDeque<>(work);
                work.clear();
                working = false;
            }
            for (Work item : failed) item.rejected.run();
        }
    }

    private void runWork() {
        while (true) {
            Work item;
            synchronized (this) {
                item = work.pollFirst();
                if (item == null) { working = false; return; }
            }
            item.action.run();
        }
    }

    public static void draw(Graphics2D graphics, BufferedImage image, Color background, int width, int height) {
        if (background.getAlpha() == 0 || width < 1 || height < 1) return;
        Graphics2D layer = (Graphics2D) graphics.create();
        try {
            layer.clipRect(0, 0, width, height);
            if (image == null) {
                layer.setColor(background);
                layer.fillRect(0, 0, width, height);
            } else {
                float parentAlpha = layer.getComposite() instanceof AlphaComposite ? ((AlphaComposite) layer.getComposite()).getAlpha() : 1;
                layer.setComposite(AlphaComposite.SrcOver.derive(parentAlpha * background.getAlpha() / 255f));
                layer.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
                double scale = Math.max(width / (double) image.getWidth(), height / (double) image.getHeight());
                int w = (int) Math.ceil(image.getWidth() * scale), h = (int) Math.ceil(image.getHeight() * scale);
                layer.drawImage(image, (width - w) / 2, (height - h) / 2, w, h, null);
            }
        } finally { layer.dispose(); }
    }

    public static final class Result {
        public final String name, error;
        Result(String name, String error) { this.name = name; this.error = error; }
    }

    private static final class Entry {
        final OverlayBackgroundImage image;
        final String error;
        final long started;
        Entry(OverlayBackgroundImage image, String error, long started) {
            this.image = image; this.error = error; this.started = started;
        }
    }

    private static final class Work {
        final Runnable action, rejected;
        Work(Runnable action, Runnable rejected) { this.action = action; this.rejected = rejected; }
    }
}

package com.improvedchat.overlay;

import com.improvedchat.ChatColorSource;
import java.awt.Color;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ChatColorConfig;

final class OverlayChatColors {
    private OverlayChatColors() { }

    static ChatColorSource resolveSource(ChatColorSource source, Client client) {
        if (source != null && source != ChatColorSource.AUTOMATIC) return source;
        return client.isResized() && client.getVarbitValue(VarbitID.CHATBOX_TRANSPARENCY) != 0
                ? ChatColorSource.TRANSPARENT : ChatColorSource.OPAQUE;
    }

    static Color sender(ChatMessageType type, ChatColorConfig colors, ChatColorSource source) {
        if (colors == null || source == ChatColorSource.WIDGET) return Color.WHITE;
        boolean opaque = source == ChatColorSource.OPAQUE;
        Color color;
        switch (type) {
            case CLAN_CHAT: case CLAN_GIM_CHAT:
                color = opaque ? colors.opaqueClanChatUsernames() : colors.transparentClanChatUsernames(); break;
            case CLAN_GUEST_CHAT:
                color = opaque ? colors.opaqueClanChatGuestUsernames() : colors.transparentClanChatGuestUsernames(); break;
            case FRIENDSCHAT:
                color = opaque ? colors.opaqueFriendsChatUsernames() : colors.transparentFriendsChatUsernames(); break;
            case PRIVATECHAT: case MODPRIVATECHAT: case PRIVATECHATOUT:
                color = opaque ? colors.opaquePrivateUsernames() : colors.transparentPrivateUsernames(); break;
            default:
                color = opaque ? colors.opaqueUsername() : colors.transparentUsername();
        }
        return color == null ? Color.WHITE : color;
    }

    static Color channel(ChatMessageType type, ChatColorConfig colors, ChatColorSource source) {
        Color color = null;
        if (colors != null && source != ChatColorSource.WIDGET) {
            boolean opaque = source == ChatColorSource.OPAQUE;
            switch (type) {
                case CLAN_CHAT: case CLAN_GIM_CHAT:
                    color = opaque ? colors.opaqueClanChannelName() : colors.transparentClanChannelName(); break;
                case CLAN_GUEST_CHAT:
                    color = opaque ? colors.opaqueClanGuestChatChannelName() : colors.transparentClanChannelGuestName(); break;
                case FRIENDSCHAT:
                    color = opaque ? colors.opaqueFriendsChatChannelName() : colors.transparentFriendsChatChannelName(); break;
                default: break;
            }
        }
        return color == null ? new Color(144, 144, 255) : color;
    }
}

package com.improvedchat.overlay;

import com.improvedchat.model.AnimatedTextStyle;
import java.awt.Color;

public final class OverlayColorSettings {
    private AnimatedTextStyle mode = AnimatedTextStyle.NORMAL;
    private Color primary = Color.WHITE;
    private Color secondary = new Color(106, 203, 255);
    private int cycleSeconds = 8;
    private boolean pulse;
    private int pulseSeconds = 4;

    public AnimatedTextStyle getMode() { return mode == null ? AnimatedTextStyle.NORMAL : mode; }
    public void setMode(AnimatedTextStyle value) { mode = value; }
    public Color getPrimary() { return primary == null ? Color.WHITE : primary; }
    public void setPrimary(Color value) { primary = value; }
    public Color getSecondary() { return secondary == null ? new Color(106, 203, 255) : secondary; }
    public void setSecondary(Color value) { secondary = value; }
    public int getCycleSeconds() { return Math.max(2, Math.min(30, cycleSeconds)); }
    public void setCycleSeconds(int value) { cycleSeconds = Math.max(2, Math.min(30, value)); }
    public boolean isPulse() { return pulse; }
    public void setPulse(boolean value) { pulse = value; }
    public int getPulseSeconds() { return Math.max(1, Math.min(60, pulseSeconds)); }
    public void setPulseSeconds(int value) { pulseSeconds = Math.max(1, Math.min(60, value)); }

    public boolean isDuo() {
        return getMode() == AnimatedTextStyle.DUO_CYCLE || getMode() == AnimatedTextStyle.DUO_WAVE;
    }

    public boolean isAnimated() {
        return getMode() != AnimatedTextStyle.NORMAL && getMode() != AnimatedTextStyle.RGB_STATIC;
    }

    public int pulseAlpha(int alpha, long now) {
        int bounded = Math.max(0, Math.min(255, alpha));
        if (!pulse) return bounded;
        long period = getPulseSeconds() * 1000L;
        double phase = Math.floorMod(now, period) / (double) period;
        return (int) Math.round(bounded * (1 + Math.cos(phase * 2 * Math.PI)) / 2);
    }
}

