package com.improvedchat.overlay;

import com.improvedchat.model.OverlayMessage;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import net.runelite.api.ChatMessageType;

public final class OverlayHistory {
    private OverlayHistory() { }

    public static List<OverlayMessage> select(List<OverlayMessage> history, long clearedThrough,
            int limit, boolean collapse) {
        return select(history, clearedThrough, limit, collapse, message -> true);
    }

    public static List<OverlayMessage> select(List<OverlayMessage> history, long clearedThrough,
            int limit, boolean collapse, java.util.function.Predicate<OverlayMessage> include) {
        List<OverlayMessage> result = new ArrayList<>();
        if (limit <= 0) return result;
        for (int i = history.size() - 1; i >= 0; i--) {
            OverlayMessage message = history.get(i);
            if (message.getSequence() <= clearedThrough || !include.test(message)) continue;
            if (collapse && !result.isEmpty()) {
                OverlayMessage newer = result.get(result.size() - 1);
                if (sameMessage(newer, message)) {
                    result.set(result.size() - 1, newer.groupedWith(message));
                    continue;
                }
            }
            if (result.size() == limit) break;
            result.add(message);
            if (!collapse && result.size() == limit) break;
        }
        java.util.Collections.reverse(result);
        return result;
    }

    private static boolean sameMessage(OverlayMessage a, OverlayMessage b) {
        return a.getType() != ChatMessageType.LOGINLOGOUTNOTIFICATION
                && a.getType() == b.getType()
                && a.isOutgoing() == b.isOutgoing()
                && Objects.equals(a.getSender(), b.getSender())
                && Objects.equals(a.getChannelName(), b.getChannelName())
                && a.getComparisonText().equals(b.getComparisonText());
    }

}

package com.improvedchat.overlay;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.function.Supplier;

final class OverlayLayoutCache {
    private final Map<Long, Entry> entries = new LinkedHashMap<Long, Entry>(64, .75f, true) {
        @Override protected boolean removeEldestEntry(Map.Entry<Long, Entry> eldest) {
            return size() > 256;
        }
    };

    synchronized void clear() { entries.clear(); }

    synchronized List<RenderLine> layout(long sequence, Object key, int alpha,
            Supplier<List<RenderLine>> factory) {
        Entry entry = entries.get(sequence);
        if (entry == null || !Objects.equals(entry.key, key)) {
            List<RenderLine> lines = new ArrayList<>();
            for (RenderLine line : factory.get()) lines.add(new RenderLine(line.segments, 255));
            entry = new Entry(key, lines);
            entries.put(sequence, entry);
        }
        if (alpha == 255) return entry.lines;
        List<RenderLine> faded = new ArrayList<>(entry.lines.size());
        for (RenderLine line : entry.lines) faded.add(new RenderLine(line.segments, alpha));
        return faded;
    }

    private static final class Entry {
        private final Object key;
        private final List<RenderLine> lines;
        private Entry(Object key, List<RenderLine> lines) { this.key = key; this.lines = lines; }
    }
}

package com.improvedchat.overlay;

import com.improvedchat.BoundedPattern;

import com.improvedchat.model.OverlayMessage;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import net.runelite.client.util.Text;

public final class OverlayMessageFilter
{
    private String wordsSnapshot = "";
    private String regexSnapshot = "";
    private String namesSnapshot = "";
    private List<Pattern> messagePatterns = new ArrayList<>();
    private List<Pattern> namePatterns = new ArrayList<>();
    private boolean safetyBlocked;

    public static boolean usesGlobalChatFilter(boolean globalOverride, OverlayConfig config)
    {
        return globalOverride || config.isUseGlobalChatFilter();
    }

    public boolean shouldExclude(OverlayConfig config, OverlayMessage message)
    {
        OverlayFilterMode mode = config.getFilterMode();
        if (mode == OverlayFilterMode.OFF)
        {
            return false;
        }

        refreshIfNeeded(config);
        if (safetyBlocked) return false;
        boolean matched = matches(message);
        if (messagePatterns.stream().anyMatch(BoundedPattern::disabled)
            || namePatterns.stream().anyMatch(BoundedPattern::disabled)) return false;
        return mode == OverlayFilterMode.HIDE_MATCHES ? matched : !matched;
    }

    public List<String> validationMessages(OverlayConfig config)
    {
        List<String> errors = new ArrayList<>();
        validateLines(config.getFilteredRegex(), false, errors);
        validateLines(config.getFilteredNames(), true, errors);
        refreshIfNeeded(config);
        if (config.getFilterMode() == OverlayFilterMode.SHOW_ONLY_MATCHES
                && messagePatterns.isEmpty() && namePatterns.isEmpty())
        {
            errors.add("No usable rules: Show Only Matches will hide every message.");
        }
        boolean limited = safetyBlocked || messagePatterns.stream().anyMatch(BoundedPattern::disabled)
            || namePatterns.stream().anyMatch(BoundedPattern::disabled);
        String warning = limited ? BoundedPattern.warning() : null;
        if (warning != null) errors.add(warning);
        return errors;
    }

    private static void validateLines(String text, boolean names, List<String> errors)
    {
        String[] lines = BoundedPattern.lines(text);
        for (int i = 0; i < lines.length; i++)
        {
            String expression = lines[i].trim();
            if (expression.isEmpty()) continue;
            if (names)
            {
                if (!expression.regionMatches(true, 0, "regex:", 0, 6)) continue;
                expression = expression.substring(6).trim();
            }
            try
            {
                if (expression.isEmpty()) throw new PatternSyntaxException("Empty expression", expression, 0);
                BoundedPattern.compile(expression, Pattern.CASE_INSENSITIVE);
            }
            catch (PatternSyntaxException ex)
            {
                errors.add((names ? "Names" : "Regex") + " line " + (i + 1) + ": " + ex.getDescription());
            }
        }
    }

    private void refreshIfNeeded(OverlayConfig config)
    {
        String words = safe(config.getFilteredWords());
        String regex = safe(config.getFilteredRegex());
        String names = safe(config.getFilteredNames());
        if (Objects.equals(words, wordsSnapshot)
            && Objects.equals(regex, regexSnapshot)
            && Objects.equals(names, namesSnapshot))
        {
            return;
        }

        wordsSnapshot = words;
        regexSnapshot = regex;
        namesSnapshot = names;

        safetyBlocked = !safeSource(words, false) || !safeSource(regex, true) || !safeSource(names, true);
        if (Text.fromCSV(BoundedPattern.source(words)).size() > BoundedPattern.MAX_RULES)
        { safetyBlocked = true; BoundedPattern.reportLimit(); }
        if (safetyBlocked)
        {
            messagePatterns = new ArrayList<>();
            namePatterns = new ArrayList<>();
            return;
        }

        List<Pattern> compiledMessages = new ArrayList<>();
        for (String word : Text.fromCSV(BoundedPattern.source(words)).stream().limit(BoundedPattern.MAX_RULES).collect(java.util.stream.Collectors.toList()))
        {
            if (!word.trim().isEmpty())
            {
                compiledMessages.add(Pattern.compile(Pattern.quote(word.trim()), Pattern.CASE_INSENSITIVE));
            }
        }

        for (String line : BoundedPattern.lines(regex))
        {
            String trimmed = line.trim();
            if (!trimmed.isEmpty())
            {
                Pattern pattern = compile(trimmed);
                if (pattern != null)
                {
                    compiledMessages.add(pattern);
                }
            }
        }

        List<Pattern> compiledNames = new ArrayList<>();
        for (String line : BoundedPattern.lines(names))
        {
            String trimmed = line.trim();
            if (trimmed.isEmpty())
            {
                continue;
            }

            Pattern pattern;
            if (trimmed.regionMatches(true, 0, "regex:", 0, 6))
            {
                pattern = compile(trimmed.substring(6).trim());
            }
            else
            {
                pattern = Pattern.compile(Pattern.quote(trimmed), Pattern.CASE_INSENSITIVE);
            }

            if (pattern != null)
            {
                compiledNames.add(pattern);
            }
        }

        messagePatterns = compiledMessages;
        namePatterns = compiledNames;
    }

    private boolean matches(OverlayMessage message)
    {
        String body = normalize(message.getMessage());
        for (Pattern pattern : messagePatterns)
        {
            if (BoundedPattern.find(pattern, body))
            {
                return true;
            }
        }

        String sender = normalize(message.getSender());
        if (!sender.isEmpty())
        {
            for (Pattern pattern : namePatterns)
            {
                if (BoundedPattern.find(pattern, sender))
                {
                    return true;
                }
            }
        }

        return false;
    }

    private static String normalize(String value)
    {
        if (value == null)
        {
            return "";
        }
        return Text.removeTags(value)
            .replace('\u00A0', ' ')
            .replace("<lt>", "<")
            .replace("<gt>", ">")
            .replace("<at>", "@");
    }

    private static Pattern compile(String expression)
    {
        if (expression.isEmpty())
        {
            return null;
        }

        try
        {
            return BoundedPattern.compile(expression, Pattern.CASE_INSENSITIVE);
        }
        catch (PatternSyntaxException ex)
        {
            return null;
        }
    }

    private static boolean safeSource(String text, boolean expressions)
    {
        if (text == null) return true;
        if (text.length() > BoundedPattern.MAX_SOURCE)
        { BoundedPattern.source(text); return false; }
        String[] lines = text.split("\\R");
        if (lines.length > BoundedPattern.MAX_RULES)
        { BoundedPattern.lines(text); return false; }
        for (String line : lines) if (expressions && line.length() > 1024)
        {
            try { BoundedPattern.compile(line, 0); }
            catch (PatternSyntaxException ignored) { }
            return false;
        }
        return true;
    }

    private static String safe(String value)
    {
        return value == null ? "" : value;
    }
}

package com.improvedchat.overlay;

import com.improvedchat.model.OverlayMessage;
import java.util.AbstractList;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import java.util.function.Predicate;

public final class OverlayMessageStore extends AbstractList<OverlayMessage> {
    private final List<OverlayMessage> messages = new ArrayList<>();
    private List<OverlayMessage> snapshot;

    public synchronized List<OverlayMessage> snapshot() {
        if (snapshot == null) snapshot = Collections.unmodifiableList(new ArrayList<>(messages));
        return snapshot;
    }

    @Override public synchronized int size() { return messages.size(); }
    @Override public synchronized OverlayMessage get(int index) { return messages.get(index); }
    @Override public synchronized int indexOf(Object value) { return messages.indexOf(value); }
    @Override public Iterator<OverlayMessage> iterator() { return snapshot().iterator(); }

    @Override public synchronized void add(int index, OverlayMessage message) {
        messages.add(index, message);
        changed();
    }

    @Override public synchronized boolean add(OverlayMessage message) {
        messages.add(message);
        changed();
        return true;
    }

    @Override public synchronized OverlayMessage set(int index, OverlayMessage message) {
        OverlayMessage previous = messages.set(index, message);
        changed();
        return previous;
    }

    @Override public synchronized OverlayMessage remove(int index) {
        OverlayMessage previous = messages.remove(index);
        changed();
        return previous;
    }

    @Override public synchronized boolean removeIf(Predicate<? super OverlayMessage> filter) {
        boolean removed = messages.removeIf(filter);
        if (removed) changed();
        return removed;
    }

    @Override public synchronized void clear() {
        messages.clear();
        changed();
    }

    private void changed() { snapshot = null; modCount++; }
}

package com.improvedchat.overlay;

import com.improvedchat.MessageColorRuleEngine;
import com.improvedchat.model.AttentionTrigger;
import com.improvedchat.model.OverlayMessage;
import java.awt.Color;
import java.util.List;
import net.runelite.api.ChatMessageType;
import net.runelite.client.config.FlashNotification;
import net.runelite.client.config.Notification;
import net.runelite.client.config.NotificationSound;
import net.runelite.client.config.RequestFocusType;
import net.runelite.client.util.Text;

public final class OverlayNotifications {
    private OverlayNotifications() { }

    public static boolean eligible(OverlayConfig config, OverlayMessage message, List<OverlayMessage> visible) {
        if (config == null || message == null || !config.isShow() || !config.getNotification().isEnabled()
                || message.isOutgoing() || message.getType() == ChatMessageType.CONSOLE) return false;

        if (visible.stream().noneMatch(item -> item.getSequence() == message.getSequence())) return false;
        return config.getNotificationTrigger() == AttentionTrigger.ALL_NEW_MESSAGES
                || MessageColorRuleEngine.flashFor(message.getMessage(), message.getType(), config.getTextSettings());
    }

    public static String message(OverlayConfig config, OverlayMessage message) {
        String sender = message.getSender() == null ? "" : Text.removeTags(message.getSender()) + ": ";
        String body = Text.removeTags(message.getMessage()).replace('\n', ' ').replace('\r', ' ');
        String result = "[" + config.getName() + "] " + sender + body;
        return result.length() > 500 ? result.substring(0, 497) + "..." : result;
    }

    public static Notification normalize(Notification value) {
        Notification n = value == null ? Notification.OFF : value;
        String name = n.getSoundName();

        if (name != null && (name.length() > 128 || name.contains("/") || name.contains("\\")
                || name.contains(":") || name.contains(".."))) name = null;
        if (name != null && name.trim().isEmpty()) name = null;
        return n.withSound(n.getSound() == null ? NotificationSound.NATIVE : n.getSound())
                .withRequestFocus(n.getRequestFocus() == null ? RequestFocusType.OFF : n.getRequestFocus())
                .withFlash(n.getFlash() == null ? FlashNotification.DISABLED : n.getFlash())
                .withFlashColor(n.getFlashColor() == null ? Color.RED : n.getFlashColor())
                .withVolume(Math.max(0, Math.min(100, n.getVolume())))
                .withTimeout(Math.max(0, n.getTimeout())).withSoundName(name);
    }
}

package com.improvedchat.overlay;

import com.improvedchat.model.OverlayMessage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;

public final class OverlayScrollback {
    private long anchor;
    private int anchorLine;
    private int pendingLines;
    private int newerMessages;

    public synchronized void scroll(int lines) {
        pendingLines = Math.max(-300, Math.min(300, pendingLines + lines));
    }

    public synchronized void latest() {
        anchor = 0;
        pendingLines = 0;
        newerMessages = 0;
    }

    public synchronized boolean isBrowsing() { return anchor != 0; }
    public synchronized int getNewerMessages() { return newerMessages; }

    public synchronized List<RenderLine> select(List<OverlayMessage> messages, int rows,
            Function<OverlayMessage, List<RenderLine>> layout) {
        if (messages.isEmpty()) {
            latest();
            return Collections.emptyList();
        }
        rows = Math.max(1, rows);
        Map<Integer, List<RenderLine>> cache = new HashMap<>();
        Function<Integer, List<RenderLine>> lines = index -> cache.computeIfAbsent(index, key -> {
            List<RenderLine> result = layout.apply(messages.get(key));
            return result.isEmpty() ? Collections.singletonList(new RenderLine(Collections.emptyList(), 255)) : result;
        });
        int last = messages.size() - 1;
        int index = last;
        if (anchor != 0) {
            index = 0;
            while (index < last && messages.get(index).getFirstSequence() < anchor) index++;
        }
        int line = anchor == 0 ? lines.apply(index).size() - 1
                : Math.min(anchorLine, lines.apply(index).size() - 1);
        int movement = pendingLines;
        pendingLines = 0;
        while (movement > 0 && (index > 0 || line > 0)) {
            if (line > 0) line--;
            else line = lines.apply(--index).size() - 1;
            movement--;
        }
        while (movement < 0 && (index < last || line < lines.apply(index).size() - 1)) {
            if (line + 1 < lines.apply(index).size()) line++;
            else { index++; line = 0; }
            movement++;
        }

        int firstIndex = index;
        int firstLine = line;
        int available = 1;
        while (available < rows && (firstIndex > 0 || firstLine > 0)) {
            if (firstLine > 0) firstLine--;
            else firstLine = lines.apply(--firstIndex).size() - 1;
            available++;
        }
        while (available < rows && (index < last || line + 1 < lines.apply(index).size())) {
            if (line + 1 < lines.apply(index).size()) line++;
            else { index++; line = 0; }
            available++;
        }
        boolean atLatest = index == last && line == lines.apply(index).size() - 1;
        anchor = atLatest ? 0 : messages.get(index).getFirstSequence();
        anchorLine = line;
        newerMessages = last - index;
        List<RenderLine> result = new ArrayList<>(rows);
        while (result.size() < rows) {
            result.add(lines.apply(index).get(line));
            if (result.size() == rows) break;
            if (line > 0) line--;
            else if (index > 0) line = lines.apply(--index).size() - 1;
            else break;
        }
        Collections.reverse(result);
        return result;
    }
}

