package com.improvedchat.release;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ProfileChanged;

@Singleton
public final class ReleaseNoticeModule
{
    static final String RELEASE = "2026-11-03-overlay-colors";
    static final String SEEN_KEY = "releaseNoticeId";
    private static final String[] UPDATES = {
        "Added a resizable chat input dock with selectable buttons and left, right or bottom overlay attachment.",
        "Overlay colors now share one Colors tab.",
        "Added Static color, Duo Cycle, Duo Wave, RGB cycle and RGB wave for borders, text and timestamps.",
        "Added independent Pulse effects and timers for each color control.",
        "Renamed message color highlights to Specific Message Highlighting.",
        "Added optional image and animated GIF backgrounds with adjustable opacity.",
    };

    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private ConfigManager configManager;
    @Inject private ChatMessageManager chat;
    @Inject private net.runelite.client.eventbus.EventBus eventBus;
    private volatile boolean running;
    private volatile int generation;

    public synchronized void startUp() { if (running) return; running = true; generation++; eventBus.register(this); schedule(); }
    public synchronized void shutDown() { if (!running) return; running = false; generation++; eventBus.unregister(this); }

    private void schedule()
    {
        final int scheduledGeneration = generation;
        clientThread.invokeLater(() -> {
            if (running && generation == scheduledGeneration) showIfNeeded();
        });
    }

    private void showIfNeeded()
    {
        if (client.getGameState() != GameState.LOGGED_IN
            || RELEASE.equals(configManager.getConfiguration("improvedchat", SEEN_KEY)))
            return;
        send("Updates:<br>* " + String.join("<br>* ", UPDATES));
        configManager.setConfiguration("improvedchat", SEEN_KEY, RELEASE);
    }

    private void send(String text)
    {
        String message = new ChatMessageBuilder().append(ChatColorType.NORMAL).append("[")
            .append(ChatColorType.HIGHLIGHT).append("Improved Chat and Overlays")
            .append(ChatColorType.NORMAL).append("] ").build() + text;
        chat.queue(QueuedMessage.builder().type(ChatMessageType.CONSOLE)
            .runeLiteFormattedMessage(message).build());
    }

    @Subscribe public void onGameStateChanged(GameStateChanged event)
    {
        if (running && event.getGameState() == GameState.LOGGED_IN) schedule();
    }

    @Subscribe public void onProfileChanged(ProfileChanged event)
    {

        generation++;
        if (running) schedule();
    }
}

package com.improvedchat;

import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.junit.Test;
import static org.junit.Assert.*;

public class BoundedPatternTest
{
    @Test public void preservesOrdinaryJavaRegexFeatures()
    {
        String[] expressions = {"(?i)dragon.*drop", "(?<=item: )\\w+", "(foo) \\1", "^\\p{L}+$", "a{2,4}", "(?s)a.b"};
        String[] messages = {"Dragon platebody drop", "item: shark", "foo foo", "RuneScape", "baaa", "a\nb", "nothing"};
        for (String regex : expressions) for (String text : messages)
        {
            Pattern pattern = BoundedPattern.compile(regex, 0);
            assertEquals(regex + " / " + text, pattern.matcher(text).find(), BoundedPattern.find(pattern, text));
        }
    }

    @Test(timeout=3000) public void pathologicalRulesAreStoppedAndStayDisabled()
    {
        Pattern pattern = BoundedPattern.compile("((a|aa)+)+$", 0);
        assertFalse(BoundedPattern.find(pattern, "a".repeat(32) + "!"));
        assertTrue(BoundedPattern.disabled(pattern));
        assertFalse(BoundedPattern.find(pattern, "a"));
        assertNotNull(BoundedPattern.warning());
        assertTrue(BoundedPattern.find(BoundedPattern.compile("a+$", 0), "aaaa"));
    }

    @Test(expected=PatternSyntaxException.class) public void oversizedExpressionIsRejected()
    { BoundedPattern.compile("a".repeat(1025), 0); }

    @Test public void ruleInputIsBoundedWithoutTruncatingStoredText()
    {
        String source = "a".repeat(BoundedPattern.MAX_SOURCE + 1);
        assertEquals("", BoundedPattern.source(source));
        assertEquals(BoundedPattern.MAX_SOURCE + 1, source.length());
        assertEquals(BoundedPattern.MAX_RULES, BoundedPattern.lines("rule\n".repeat(200)).length);
    }
}

