package com.improvedchat.overlay;

import com.improvedchat.model.OverlayMessage;
import java.util.Arrays;
import java.util.List;
import net.runelite.api.ChatMessageType;
import org.junit.Test;
import static org.junit.Assert.*;

public class OverlayHistoryTest {
    private OverlayMessage chat(ChatMessageType type, String channel, boolean outgoing, String body) {
        return OverlayMessage.senderMessage("Alice", channel, body, 123, type, outgoing);
    }

    @Test public void sameTextAcrossChannelsOrDirectionsRemainsSeparate() {
        List<OverlayMessage> messages = Arrays.asList(
                chat(ChatMessageType.PUBLICCHAT, null, false, "hello"),
                chat(ChatMessageType.CLAN_CHAT, "Clan A", false, "hello"),
                chat(ChatMessageType.CLAN_CHAT, "Clan B", false, "hello"),
                chat(ChatMessageType.CLAN_CHAT, "Clan B", true, "hello"));
        assertEquals(4, OverlayHistory.select(messages, 0, 20, true).size());
    }

    @Test public void onlyConsecutiveMessagesCollapseAndSharedHistoryIsUnchanged() {
        OverlayMessage first = chat(ChatMessageType.CLAN_CHAT, "A", false, "<col=ff0000>hello</col>");
        OverlayMessage second = chat(ChatMessageType.CLAN_CHAT, "A", false, "hello");
        OverlayMessage third = chat(ChatMessageType.CLAN_CHAT, "A", false, "different");
        OverlayMessage fourth = chat(ChatMessageType.CLAN_CHAT, "A", false, "hello");
        List<OverlayMessage> history = Arrays.asList(first, second, third, fourth);
        List<OverlayMessage> view = OverlayHistory.select(history, 0, 20, true);
        assertEquals(3, view.size());
        assertEquals(2, view.get(0).getCount());
        assertEquals(second.getSequence(), view.get(0).getSequence());
        assertEquals(4, history.size());
        for (OverlayMessage message : history) assertEquals(1, message.getCount());
    }

    @Test public void clearBoundaryIsLocalAndNewDuplicateStartsAtOne() {
        OverlayMessage before = chat(ChatMessageType.PUBLICCHAT, null, false, "hello");
        long clearedThrough = OverlayMessage.latestSequence();
        OverlayMessage after = chat(ChatMessageType.PUBLICCHAT, null, false, "hello");
        List<OverlayMessage> history = Arrays.asList(before, after);
        List<OverlayMessage> cleared = OverlayHistory.select(history, clearedThrough, 20, true);
        assertEquals(1, cleared.size());
        assertEquals(1, cleared.get(0).getCount());
        assertEquals(2, OverlayHistory.select(history, 0, 20, true).get(0).getCount());
    }

    @Test public void delayedRewriteCannotReappearAfterClear() {
        OverlayMessage command = chat(ChatMessageType.CLAN_CHAT, "A", false, "!kc");
        long clearedThrough = OverlayMessage.latestSequence();
        OverlayMessage rewritten = command.withBody("Kill count: 123");
        assertEquals(command.getSequence(), rewritten.getSequence());
        assertEquals(command.getTimestamp(), rewritten.getTimestamp());
        assertTrue(OverlayHistory.select(Arrays.asList(rewritten), clearedThrough, 20, true).isEmpty());
        assertEquals(1, OverlayHistory.select(Arrays.asList(rewritten), 0, 20, true).size());
    }

    @Test public void delayedFinalBodiesCollapseWithoutLosingRawEntries() {
        OverlayMessage a = chat(ChatMessageType.PUBLICCHAT, null, false, ":)");
        OverlayMessage b = chat(ChatMessageType.PUBLICCHAT, null, false, "<img=42>");
        assertEquals(2, OverlayHistory.select(Arrays.asList(a, b), 0, 20, true).size());
        List<OverlayMessage> view = OverlayHistory.select(Arrays.asList(a.withBody("<img=42>"), b), 0, 20, true);
        assertEquals(1, view.size());
        assertEquals(2, view.get(0).getCount());
    }

    @Test public void limitAppliesAfterCollapsingAndIncludesNotifications() {
        OverlayMessage a = chat(ChatMessageType.PUBLICCHAT, null, false, "hello");
        OverlayMessage b = chat(ChatMessageType.PUBLICCHAT, null, false, "hello");
        OverlayMessage notification = OverlayMessage.loginNotification("Bob", "logged in", 123, 5);
        List<OverlayMessage> view = OverlayHistory.select(Arrays.asList(a, b, notification), 0, 2, true);
        assertEquals(2, view.size());
        assertEquals(2, view.get(0).getCount());
        assertSame(notification, view.get(1));
        assertEquals(2, OverlayHistory.select(Arrays.asList(notification, notification), 0, 20, true).size());
    }
}

package com.improvedchat.overlay;

import com.improvedchat.ImprovedChatConfig;
import com.improvedchat.ImprovedChatPlugin;
import com.improvedchat.chatbox.offline.ClanChatPresentationService;
import com.improvedchat.model.PlacementMode;
import java.awt.Dimension;
import java.awt.Point;
import java.lang.reflect.Constructor;
import java.lang.reflect.Method;
import java.util.Collection;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.RuneLiteConfig;
import net.runelite.client.events.ProfileChanged;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.OverlayPosition;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class OverlayInterfaceLayerTest {
    private static final int[] LAYOUTS = {InterfaceID.TOPLEVEL, InterfaceID.TOPLEVEL_PRE_EOC, InterfaceID.TOPLEVEL_OSRS_STRETCH};

    @Test public void realManagerKeepsSavedDraggedSnappedAndPlayerOverlaysBehindInterfaces() throws Exception {
        for (int layout : LAYOUTS) {
            Client client = mock(Client.class);
            when(client.isResized()).thenReturn(layout != InterfaceID.TOPLEVEL);
            when(client.getTopLevelInterfaceId()).thenReturn(layout);
            ConfigManager settings = mock(ConfigManager.class);
            Point saved = new Point(120, 150);
            Dimension size = new Dimension(300, 120);
            when(settings.getConfiguration(eq(RuneLiteConfig.GROUP_NAME), anyString(), eq(Point.class))).thenReturn(saved);
            when(settings.getConfiguration(eq(RuneLiteConfig.GROUP_NAME), anyString(), eq(Dimension.class))).thenReturn(size);
            OverlayManager manager = manager(client, settings);
            OverlayConfig config = new OverlayConfig();
            DynamicChatOverlay overlay = new DynamicChatOverlay(mock(ImprovedChatPlugin.class), new ImprovedChatConfig(){},
                    client, null, new ClanChatPresentationService(), config);
            manager.add(overlay);
            assertEquals(saved, overlay.getPreferredLocation());
            assertEquals(size, overlay.getPreferredSize());
            assertBehind(manager, overlay);

            overlay.setPreferredLocation(new Point(300, 200));
            manager.saveOverlay(overlay);
            assertBehind(manager, overlay);
            overlay.setPreferredPosition(OverlayPosition.TOP_RIGHT);
            manager.saveOverlay(overlay);
            assertBehind(manager, overlay);
            manager.onProfileChanged(new ProfileChanged());
            assertEquals(saved, overlay.getPreferredLocation());
            assertBehind(manager, overlay);

            for (PlacementMode mode : PlacementMode.values()) {
                config.setPlacementMode(mode);
                overlay.setOverlayConfig(config);
                manager.remove(overlay);
                manager.add(overlay);
                overlay.preview();
                assertBehind(manager, overlay);
            }
        }
    }

    private static OverlayManager manager(Client client, ConfigManager settings) throws Exception {
        Constructor<?> constructor = OverlayManager.class.getDeclaredConstructors()[0];
        constructor.setAccessible(true);
        Class<?>[] types = constructor.getParameterTypes();
        Object[] args = new Object[types.length];
        for (int i = 0; i < types.length; i++) {
            args[i] = types[i] == Client.class ? client : types[i] == ConfigManager.class ? settings : mock(types[i]);
        }
        return (OverlayManager) constructor.newInstance(args);
    }

    private static void assertBehind(OverlayManager manager, Overlay overlay) throws Exception {
        Method layer = OverlayManager.class.getDeclaredMethod("getLayer", OverlayLayer.class);
        layer.setAccessible(true);
        assertTrue(((Collection<?>) layer.invoke(manager, OverlayLayer.ABOVE_SCENE)).contains(overlay));
        assertFalse(((Collection<?>) layer.invoke(manager, OverlayLayer.ALWAYS_ON_TOP)).contains(overlay));
        Method after = OverlayManager.class.getDeclaredMethod("getForInterface", int.class);
        after.setAccessible(true);
        for (int layout : LAYOUTS) {
            assertFalse("Must never be promoted above a game interface", ((Collection<?>) after.invoke(manager, layout)).contains(overlay));
        }
    }
}

package com.improvedchat.overlay;

import com.google.gson.Gson;
import com.improvedchat.ImprovedChatConfig;
import com.improvedchat.MessageColorRuleEngine;
import com.improvedchat.RainbowStyle;
import com.improvedchat.model.AnimatedTextStyle;
import com.improvedchat.model.FontSize;
import com.improvedchat.model.OverlayMessage;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.List;
import net.runelite.api.ChatMessageType;
import org.junit.Test;
import static org.junit.Assert.*;

public class OverlayMenuMigrationTest {
    private final Gson gson = new Gson();
    private ImprovedChatConfig legacy() {
        return new ImprovedChatConfig() {
            public boolean enableMessageColorRules() { return true; }
            public String messageColorRules() { return "expire::9::flash\nregex:^Loot::3"; }
            public Color messageRuleColor9() { return Color.PINK; }
            public boolean includePlayerChatInColorRules() { return true; }
            public boolean enableOverlayRainbowRules() { return true; }
            public String overlayRainbowRules() { return "rainbow\nregex:^Congratulations"; }
            public RainbowStyle rainbowStyle() { return RainbowStyle.PER_LETTER; }
            public Color privateColour() { return Color.ORANGE; }
        };
    }

    @Test public void oldJsonMigratesOnceWithoutChangingIdentityGeometryOrAnimation() {
        OverlayConfig old = OverlayConfigStore.read(gson,
                "[{\"id\":\"saved-id\",\"name\":\"Saved\",\"widgetWidth\":730,\"offsetX\":42,\"show\":false,\"animatedTextStyle\":\"RGB_CYCLE\",\"rgbCycleSeconds\":17}]").get(0);
        assertFalse(old.hasTextSettings());
        assertTrue(old.migrateTextSettings(legacy()));
        assertEquals("saved-id", old.getId());
        assertEquals(730, old.getWidgetWidth());
        assertEquals(42, old.getOffsetX());
        assertFalse(old.isShow());
        assertEquals(AnimatedTextStyle.RGB_CYCLE, old.getAnimatedTextStyle());
        assertFalse(old.isCustomRgbCycle());
        assertEquals(17, old.getRgbCycleSeconds());
        OverlayTextSettings settings = old.getTextSettings();
        assertEquals(legacy().messageColorRules(), settings.messageColorRules());
        assertEquals(Color.PINK, settings.getPalette(8));
        assertEquals(RainbowStyle.PER_LETTER, settings.rainbowStyle());
        assertEquals(Color.ORANGE, settings.privateColour());
        assertFalse(settings.isHighlightsOverrideDefaults());
        settings.setSolidRules("my edit::2");
        assertFalse(old.migrateTextSettings(new ImprovedChatConfig() { }));
        assertEquals("my edit::2", settings.messageColorRules());
        OverlayConfig roundTrip = OverlayConfigStore.read(gson, "[" + gson.toJson(old) + "]").get(0);
        assertFalse(roundTrip.migrateTextSettings(legacy()));
        assertEquals(gson.toJson(old), gson.toJson(roundTrip));
    }

    @Test public void migrationAndDuplicateCopiesKeepRulePalettesIndependent() {
        OverlayConfig a = new OverlayConfig(), b = new OverlayConfig();
        a.migrateTextSettings(legacy()); b.migrateTextSettings(legacy());
        a.getTextSettings().setPalette(8, Color.BLUE);
        assertEquals(Color.PINK, b.getTextSettings().getPalette(8));
        OverlayConfig copy = gson.fromJson(gson.toJson(a), OverlayConfig.class);
        copy.renewId(); copy.getTextSettings().setPalette(8, Color.GREEN);
        assertNotEquals(a.getId(), copy.getId());
        assertEquals(Color.BLUE, a.getTextSettings().getPalette(8));
        assertEquals(Color.GREEN, copy.getTextSettings().getPalette(8));
        assertEquals(Color.BLUE, MessageColorRuleEngine.colorFor("will expire", ChatMessageType.GAMEMESSAGE, a.getTextSettings()));
    }

    @Test public void emptySavedListsStayEmptyAndDisabledDefinitionsArePreserved() {
        assertTrue(OverlayConfigStore.read(gson, "[]").isEmpty());
        ImprovedChatConfig disabled = new ImprovedChatConfig() {
            public String messageColorRules() { return "saved but disabled::7::flash"; }
            public String overlayRainbowRules() { return "saved rgb rule"; }
        };
        OverlayConfig c = new OverlayConfig(); c.migrateTextSettings(disabled);
        assertFalse(c.getTextSettings().enableMessageColorRules());
        assertEquals(disabled.messageColorRules(), c.getTextSettings().messageColorRules());
        assertFalse(c.getTextSettings().enableOverlayRainbowRules());
        assertEquals(disabled.overlayRainbowRules(), c.getTextSettings().overlayRainbowRules());
    }

    private List<RenderLine> lines(OverlayConfig c, String text, boolean wrap) {
        Graphics2D graphics = new BufferedImage(500, 100, BufferedImage.TYPE_INT_ARGB).createGraphics();
        graphics.setFont(new Font("Dialog", Font.PLAIN, 12));
        try {
            return ChatRenderUtils.buildMessageLines(OverlayMessage.gameMessage(text, 0, ChatMessageType.GAMEMESSAGE, false),
                    graphics.getFontMetrics(), 90, 0, 0, wrap, Color.WHITE, c.isContextualColours(), false,
                    FontSize.REGULAR, null, false, "", false, null, Collections.emptyList(), null, c);
        } finally { graphics.dispose(); }
    }

    @Test public void matchedMessageOverridesAnimationWithoutStylingOtherMessages() {
        for (boolean wrap : new boolean[]{false, true}) {
            OverlayConfig c = new OverlayConfig(); c.migrateTextSettings(legacy());
            c.setAnimatedTextStyle(AnimatedTextStyle.RGB_WAVE);
            c.getTextSettings().setHighlightsOverrideDefaults(true);
            for (RenderLine line : lines(c, "expire expire expire", wrap)) for (TextSegment segment : line.segments) {
                if (segment.iconId < 0) {
                    assertEquals(AnimatedTextStyle.NORMAL, segment.textStyle);
                    assertEquals(Color.PINK, segment.color);
                }
            }
            for (RenderLine line : lines(c, "unmatched", wrap)) for (TextSegment segment : line.segments) assertNull(segment.textStyle);
            c.getTextSettings().setHighlightStyle(AnimatedTextStyle.RGB_CYCLE);
            for (RenderLine line : lines(c, "rainbow", wrap)) for (TextSegment segment : line.segments) assertEquals(AnimatedTextStyle.RGB_CYCLE, segment.textStyle);
            c.getTextSettings().setHighlightsOverrideDefaults(false);
            for (RenderLine line : lines(c, "expire", wrap)) for (TextSegment segment : line.segments) assertNull(segment.textStyle);
        }
    }

    @Test public void migratedRainbowKeepsCharacterSpreadAndIcons() {
        OverlayConfig c = new OverlayConfig(); c.migrateTextSettings(legacy());
        List<TextSegment> segments = lines(c, "rainbow <img=2>", true).get(0).segments;
        assertEquals(1, segments.get(0).text.length());
        assertTrue(segments.stream().anyMatch(s -> s.iconId == 2));
        assertEquals(AnimatedTextStyle.RGB_STATIC, segments.get(0).textStyle);
    }

    @Test public void customCycleHitsBothEndpointsRestoresAlphaAndKeepsFullSpectrumDefault() {
        OverlayConfig c = new OverlayConfig();
        c.setRgbCycleSeconds(8); c.setCustomRgbCycle(true);
        c.setRgbColor1(Color.RED); c.setRgbColor2(Color.BLUE);
        assertEquals(new Color(255,0,0,91), RgbAnimation.cycleColor(c, 0, 91));
        assertEquals(new Color(0,0,255,91), RgbAnimation.cycleColor(c, 4000, 91));
        assertEquals(new Color(255,0,0,91), RgbAnimation.cycleColor(c, 8000, 91));
        c.setCustomRgbCycle(false);
        assertNotEquals(RgbAnimation.cycleColor(c, 0, 255), RgbAnimation.cycleColor(c, 2000, 255));
    }
}

package com.improvedchat.overlay;

import com.improvedchat.ImprovedChatConfig;
import com.improvedchat.model.OverlayMessage;
import net.runelite.api.ChatMessageType;
import net.runelite.client.config.ConfigItem;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class OverlayMessageFilterTest
{
    @Test
    public void reportsInvalidRuleLinesAndEmptyShowOnlyMode()
    {
        OverlayConfig config = new OverlayConfig();
        config.setFilterMode(OverlayFilterMode.SHOW_ONLY_MATCHES);
        config.setFilteredRegex("\n[invalid");
        config.setFilteredNames("regex:");
        java.util.List<String> errors = new OverlayMessageFilter().validationMessages(config);
        assertEquals(3, errors.size());
        assertTrue(errors.get(0).startsWith("Regex line 2:"));
        assertTrue(errors.get(1).startsWith("Names line 1:"));
        assertTrue(errors.get(2).contains("hide every message"));
        config.setFilteredWords("hello");
        assertEquals(2, new OverlayMessageFilter().validationMessages(config).size());
    }

    @Test
    public void newOverlayDefaultsDoNotChangeExistingBehavior()
    {
        OverlayConfig config = new OverlayConfig();
        assertFalse(config.isUseGlobalChatFilter());
        assertEquals(OverlayFilterMode.OFF, config.getFilterMode());
        assertEquals("", config.getFilteredWords());
        assertEquals("", config.getFilteredRegex());
        assertEquals("", config.getFilteredNames());
    }

    @Test
    public void globalOverrideTakesPrecedence()
    {
        OverlayConfig config = new OverlayConfig();
        assertFalse(OverlayMessageFilter.usesGlobalChatFilter(false, config));

        config.setUseGlobalChatFilter(true);
        assertTrue(OverlayMessageFilter.usesGlobalChatFilter(false, config));

        config.setUseGlobalChatFilter(false);
        assertTrue(OverlayMessageFilter.usesGlobalChatFilter(true, config));
    }

    @Test
    public void hideMatchesSupportsWordsAndRegex()
    {
        OverlayConfig config = new OverlayConfig();
        config.setFilterMode(OverlayFilterMode.HIDE_MATCHES);
        config.setFilteredWords("buy gold, spam phrase");
        config.setFilteredRegex("^You have .* coins$");

        OverlayMessageFilter filter = new OverlayMessageFilter();
        assertTrue(filter.shouldExclude(config,
            OverlayMessage.gameMessage("BUY GOLD now", 0, ChatMessageType.GAMEMESSAGE, false)));
        assertTrue(filter.shouldExclude(config,
            OverlayMessage.gameMessage("You have 42 coins", 0, ChatMessageType.GAMEMESSAGE, false)));
        assertFalse(filter.shouldExclude(config,
            OverlayMessage.gameMessage("A normal message", 0, ChatMessageType.GAMEMESSAGE, false)));
    }

    @Test
    public void showOnlyMatchesInvertsTheDecision()
    {
        OverlayConfig config = new OverlayConfig();
        config.setFilterMode(OverlayFilterMode.SHOW_ONLY_MATCHES);
        config.setFilteredWords("collection log");

        OverlayMessageFilter filter = new OverlayMessageFilter();
        assertFalse(filter.shouldExclude(config,
            OverlayMessage.gameMessage("Collection log updated", 0, ChatMessageType.GAMEMESSAGE, false)));
        assertTrue(filter.shouldExclude(config,
            OverlayMessage.gameMessage("You eat the shark.", 0, ChatMessageType.GAMEMESSAGE, false)));
    }

    @Test
    public void senderRulesSupportLiteralAndRegexEntries()
    {
        OverlayConfig config = new OverlayConfig();
        config.setFilterMode(OverlayFilterMode.HIDE_MATCHES);
        config.setFilteredNames("Alice\nregex:^Bob[0-9]+$");

        OverlayMessageFilter filter = new OverlayMessageFilter();
        assertTrue(filter.shouldExclude(config,
