        return OverlayMessage.gameMessage(text, 1, ChatMessageType.GAMEMESSAGE, false);
    }
    private List<RenderLine> layout(OverlayMessage m) {
        return Arrays.stream(m.getMessage().split("\\|"))
                .map(s -> new RenderLine(Collections.singletonList(new TextSegment(s, -1, 10, Color.WHITE)),255))
                .collect(Collectors.toList());
    }
    private String page(OverlayScrollback s, List<OverlayMessage> messages, int rows) {
        return s.select(messages,rows,this::layout).stream().map(l -> l.segments.get(0).text).collect(Collectors.joining("|"));
    }

    @Test public void scrollsWrappedLinesAndAnchorsWhileNewMessagesArrive() {
        OverlayScrollback s = new OverlayScrollback();
        List<OverlayMessage> messages = new ArrayList<>(Arrays.asList(message("a|b|c|d"), message("e|f|g")));
        assertEquals("e|f|g",page(s,messages,3));
        s.scroll(2); assertEquals("c|d|e",page(s,messages,3));
        messages.add(message("h|i"));
        assertEquals("c|d|e",page(s,messages,3));
        assertTrue(s.isBrowsing()); assertEquals(1,s.getNewerMessages());
        s.scroll(-300); assertEquals("g|h|i",page(s,messages,3)); assertFalse(s.isBrowsing());
        messages.add(message("j")); assertEquals("h|i|j",page(s,messages,3));
    }

    @Test public void oldestPageEvictionClearAndResizeStayInRange() {
        OverlayScrollback s = new OverlayScrollback();
        List<OverlayMessage> messages = new ArrayList<>(Arrays.asList(message("a|b"),message("c|d"),message("e|f")));
        s.scroll(300); assertEquals("a|b|c",page(s,messages,3));
        s.scroll(300); assertEquals("a|b|c",page(s,messages,3));
        messages.remove(0); assertEquals("c|d|e",page(s,messages,3));
        assertEquals("c|d|e|f",page(s,messages,20)); assertFalse(s.isBrowsing());
        s.scroll(2); page(s,messages,2); s.latest(); assertEquals("e|f",page(s,messages,2));
        s.scroll(2); page(s,messages,2); assertEquals("",page(s,Collections.emptyList(),2)); assertFalse(s.isBrowsing());
        messages=Collections.singletonList(message("new")); assertEquals("new",page(s,messages,2));
    }

    @Test public void collapsedDuplicatesKeepStableIdentityAndNewestNotificationSequence() {
        OverlayMessage a=message("one|two|three|four"), b=message("one|two|three|four");
        List<OverlayMessage> raw=new ArrayList<>(Arrays.asList(a,b));
        OverlayScrollback s=new OverlayScrollback(); s.scroll(1);
        List<OverlayMessage> grouped=OverlayHistory.select(raw,0,100,true);
        assertEquals(b.getSequence(),grouped.get(0).getSequence());
        assertEquals(a.getSequence(),grouped.get(0).getFirstSequence());
        assertEquals("two|three",page(s,grouped,2));
        raw.add(message("one|two|three|four"));
        assertEquals("two|three",page(s,OverlayHistory.select(raw,0,100,true),2));
    }

    @Test public void largeHistoryOnlyFormatsNeededMessages() {
        List<OverlayMessage> messages=new ArrayList<>();
        for(int i=0;i<5000;i++)messages.add(message("message "+i));
        AtomicInteger layouts=new AtomicInteger(); OverlayScrollback s=new OverlayScrollback();
        assertEquals(10,s.select(messages,10,m->{layouts.incrementAndGet();return layout(m);}).size());
        assertEquals(10,layouts.get());
        s.scroll(3); layouts.set(0);
        s.select(messages,10,m->{layouts.incrementAndGet();return layout(m);});
        assertTrue(layouts.get()<=13);
    }
}

package com.improvedchat.overlay;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.improvedchat.BoundedPattern;
import com.improvedchat.model.OverlayMessage;
import net.runelite.api.ChatMessageType;
import org.junit.Test;
import static org.junit.Assert.*;

public class OverlaySecurityTest
{
    @Test(timeout=3000) public void costlyShowOnlyRuleDoesNotBlankTheOverlay()
    {
        OverlayConfig config = new OverlayConfig();
        config.setFilterMode(OverlayFilterMode.SHOW_ONLY_MATCHES);
        config.setFilteredRegex("((a|aa)+)+$");
        OverlayMessageFilter filter = new OverlayMessageFilter();
        assertFalse(filter.shouldExclude(config, OverlayMessage.gameMessage(
            "a".repeat(32) + "!", 0, ChatMessageType.GAMEMESSAGE, false)));
        assertFalse(filter.shouldExclude(config, OverlayMessage.gameMessage(
            "another message", 0, ChatMessageType.GAMEMESSAGE, false)));
        assertFalse(filter.validationMessages(config).isEmpty());
        assertEquals("((a|aa)+)+$", config.getFilteredRegex());
        config.setFilteredRegex("^allowed$");
        assertTrue(filter.shouldExclude(config, OverlayMessage.gameMessage(
            "not allowed", 0, ChatMessageType.GAMEMESSAGE, false)));
    }

    @Test public void oversizedRuleSourceLeavesMessagesVisibleAndSettingsUntouched()
    {
        OverlayConfig config = new OverlayConfig();
        config.setFilterMode(OverlayFilterMode.SHOW_ONLY_MATCHES);
        String source = "a".repeat(BoundedPattern.MAX_SOURCE+1);
        config.setFilteredRegex(source);
        assertFalse(new OverlayMessageFilter().shouldExclude(config, OverlayMessage.gameMessage(
            "message", 0, ChatMessageType.GAMEMESSAGE, false)));
        assertEquals(source, config.getFilteredRegex());
    }

    @Test(expected=JsonParseException.class) public void rejectsOversizedConfigurationBeforeParsing()
    { OverlayConfigStore.read(new Gson(), " ".repeat(OverlayConfigStore.MAX_JSON+1)); }

    @Test(expected=JsonParseException.class) public void rejectsExcessiveOverlayCount()
    { OverlayConfigStore.read(new Gson(), "[" + "{},".repeat(64) + "{}]"); }

    @Test(expected=JsonParseException.class) public void rejectsDeepUnknownFields()
    { OverlayConfigStore.read(new Gson(), "[{\"unused\":" + "[".repeat(33) + "0" + "]".repeat(33) + "}]"); }

    @Test public void quotedBracesAndEscapesDoNotCountAsNesting()
    {
        OverlayConfig config = new OverlayConfig();
        config.setName("[{}]\\\"".repeat(40));
        Gson gson = new Gson();
        assertEquals(config.getName(), OverlayConfigStore.read(gson, gson.toJson(
            java.util.Collections.singletonList(config))).get(0).getName());
    }
}

package com.improvedchat.overlay;

import com.google.gson.Gson;
import com.improvedchat.MessageColorRuleEngine;
import com.improvedchat.model.FontSize;
import com.improvedchat.model.OverlayMessage;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.stream.Collectors;
import net.runelite.api.ChatMessageType;
import org.junit.Test;
import static org.junit.Assert.*;

public class OverlayTextReplacementsTest {
    private static final String ORIGINAL = "Your thrall returns to the grave.";
    private static final String REPLACEMENT = "You need to summon a thrall!";
    private OverlayConfig configured() {
        OverlayConfig c = new OverlayConfig(); c.setMessageReplacerEnabled(true);
        c.setTextReplacements(Arrays.asList(new OverlayTextReplacement(ORIGINAL,REPLACEMENT,true),
                new OverlayTextReplacement("Your boost expired.","Drink another potion!",true)));
        return c;
    }
    @Test public void multipleMessagesMatchIndependentlyIgnoringChatColorsAndCase() {
        OverlayConfig c = configured();
        assertEquals(REPLACEMENT, OverlayTextReplacements.displayText(c,"<col=ff0000>YOUR THRALL RETURNS TO THE GRAVE.</col>"));
        assertEquals("Drink another potion!",OverlayTextReplacements.displayText(c,"Your boost expired."));
        assertEquals("unmatched",OverlayTextReplacements.displayText(c,"unmatched"));
        assertEquals(ORIGINAL + " Again.",OverlayTextReplacements.displayText(c,ORIGINAL + " Again."));
    }
    @Test public void disabledIncompleteAndNullRulesLeaveMessagesUntouched() {
        OverlayConfig c = configured(); c.setMessageReplacerEnabled(false);
        assertEquals(ORIGINAL,OverlayTextReplacements.displayText(c,ORIGINAL));
        c.setMessageReplacerEnabled(true);
        c.setTextReplacements(Arrays.asList(null,new OverlayTextReplacement(ORIGINAL,REPLACEMENT,false),new OverlayTextReplacement(ORIGINAL,"",true)));
        assertEquals(ORIGINAL,OverlayTextReplacements.displayText(c,ORIGINAL));
        assertNull(OverlayTextReplacements.displayText(c,null));
    }
    @Test public void firstMatchWinsAndReplacementsNeverChain() {
        OverlayConfig c = configured();
        c.setTextReplacements(Arrays.asList(new OverlayTextReplacement(ORIGINAL,REPLACEMENT,true),
                new OverlayTextReplacement(ORIGINAL,"duplicate",true),new OverlayTextReplacement(REPLACEMENT,"recursive",true)));
        assertEquals(REPLACEMENT,OverlayTextReplacements.displayText(c,ORIGINAL));
    }
    @Test public void outputIsLiteralTextAndSettingsRoundTripWithoutSharedCopies() {
        OverlayConfig c = configured(); Gson gson = new Gson();
        c.normalize();
        c.setTextReplacements(Collections.singletonList(new OverlayTextReplacement(ORIGINAL,"Use <ruby> & <img=2>",true)));
        String value=OverlayTextReplacements.displayText(c,ORIGINAL);
        assertEquals("Use <ruby> & <img=2>",MessageColorRuleEngine.plainText(value));
        assertFalse(value.contains("<img=2>"));
        OverlayConfig copy=OverlayConfigStore.read(gson,"["+gson.toJson(c)+"]").get(0);
        assertEquals(gson.toJson(c),gson.toJson(copy));
        copy.setTextReplacements(Collections.emptyList());
        assertEquals(1,c.getTextReplacements().size());
    }
    @Test public void oldSavedSettingsDefaultToOff() {
        OverlayConfig old = OverlayConfigStore.read(new Gson(),"[{\"id\":\"old\",\"name\":\"Old overlay\"}]").get(0);
        assertFalse(old.isMessageReplacerEnabled()); assertTrue(old.getTextReplacements().isEmpty());
        assertEquals(ORIGINAL,OverlayTextReplacements.displayText(old,ORIGINAL));
    }
    @Test public void renderedReplacementKeepsOriginalHistoryHighlightFilterAndDuplicateCount() {
        OverlayConfig c=configured(); c.getTextSettings().setSolidEnabled(true);
        c.getTextSettings().setSolidRules("thrall returns::1::flash"); c.getTextSettings().setPalette(0,Color.BLUE);
        c.setFilterMode(OverlayFilterMode.SHOW_ONLY_MATCHES); c.setFilteredWords("thrall returns");
        OverlayMessage m=OverlayMessage.gameMessage(ORIGINAL,0,ChatMessageType.GAMEMESSAGE,false);
        m.incrementCount();
        assertFalse(new OverlayMessageFilter().shouldExclude(c,m));
        assertTrue(MessageColorRuleEngine.flashFor(m.getMessage(),m.getType(),c.getTextSettings()));
        Graphics2D g=new BufferedImage(500,150,BufferedImage.TYPE_INT_ARGB).createGraphics();
        try {
            for(boolean wrap:new boolean[]{true,false}) {
                List<RenderLine> lines=ChatRenderUtils.buildMessageLines(m,g.getFontMetrics(),90,0,0,wrap,Color.WHITE,true,false,
                        FontSize.REGULAR,null,false,"",false,null,Collections.emptyList(),null,c);
                String visible=lines.stream().map(line -> line.segments.stream().map(segment->segment.text).collect(Collectors.joining())).collect(Collectors.joining(wrap ? " " : ""));
                assertEquals(REPLACEMENT + " (2)",visible);
                assertTrue(lines.stream().flatMap(line->line.segments.stream()).allMatch(segment->Color.BLUE.equals(segment.color)));
                assertEquals(ORIGINAL,m.getMessage());
            }
        } finally {g.dispose();}
        assertEquals(ORIGINAL,OverlayTextReplacements.displayText(new OverlayConfig(),m.getMessage()));
    }
}

